#include <ESP8266WebServer.h>
#include <ESP8266mDNS.h>

ESP8266WebServer server(80);

String getPage();

void preklopi_relej(int relej)
{
    digitalWrite(relej, HIGH);
    delay(500);
    digitalWrite(relej, LOW);
}

void setup()
{
    Serial.begin(9600);

    pinMode(RELEJ_1, OUTPUT);
    pinMode(RELEJ_2, OUTPUT);

    WiFi.begin("A1_586972105", "Suvidol012");

    while (WiFi.status() != WL_CONNECTED)
    {
        delay(1000);
        Serial.println("Connecting to WiFi...");
    }

    if (!MDNS.begin("mdv"))
    {
        Serial.println("Error setting up MDNS responder!");
        while (1)
        {
            delay(1000);
        }
    }

    Serial.println("mDNS responder started");
    MDNS.addService("http", "tcp", 80);

    server.on("/", HTTP_GET, []()
              { server.send(200, "text/html", getPage()); });

    server.on("/toggle1", HTTP_GET, []()
              {
        preklopi_relej(RELEJ_1);
        server.send(200, "text/html", getPage()); });

    server.on("/toggle2", HTTP_GET, []()
              {
        preklopi_relej(RELEJ_2);
        server.send(200, "text/html", getPage()); });

    server.begin();
}

void loop()
{
    server.handleClient();
    MDNS.update();
}

String getPage()
{
    String page = "<html lang=\"hr\">\
    <head>\
      <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\
    </head>\
    <style>\
        button {\
        width: 150px;\
        height: 150px;\
        font-size: 40px;\
        }\
    </style>\
    <body style='display: flex;'>\
      <div style='display: flex; justify-content: center; align-items: center; flex-direction: column; width: 100%;'>\
        <h1 style='text-align: center;'>Dvorisna Vrata</h1>\
        <br>\
        <div style='display: flex;'>\
            <a href=\"/toggle1\"><button>Pritisni 1</button></a>\
            <a href=\"/toggle2\"><button>Pritisni 2</button></a>\
        </div>\
      </div>\
    </body>\
  </html>";
    return page;
}
